local function assign(p1, ...) -- line: 1
    assert(type(p1) == "table", (("Expected a table for first argument, got $%*"):format((type(p1)))))

    for i = 1, select("#", ...) do
        for v3, v4 in (select(i, ...)) do
            p1[v3] = v4
        end
    end

    return p1
end

return assign
